mapper.select:
SELECT id, project_id, chapter_id, source_type, source_text, rewrite_mode, instruction,
       status, segments_json, result_text, diff_payload, created_at, completed_at
FROM story_rewrite_task
WHERE project_id = #{projectId}
ORDER BY COALESCE(completed_at, created_at) DESC, id DESC
LIMIT #{limit}
